\section{Introduction}

\subsection{Poisson summation as a rigidity phenomenon}

Poisson summation relates a sum of a function over a lattice to a sum of its Fourier
transform over the dual lattice; it underlies sampling theory, theta transformation laws,
lattice point counting and the analytic theory of modular forms. Its finite analogue on a
finite abelian group $G$ is a statement of finite-dimensional linear algebra: for every
subgroup $H\le G$,
\begin{equation}\label{eq:poisson}
|G|\sum_{x\in H}f(x)\;=\;|H|\sum_{\psi\in H^{\perp}}\Fh f(\psi)\qquad (f\colon G\to\mathbb{C}).
\end{equation}

The identity is invariably stated as a theorem \emph{about subgroups}. This paper answers the
question the statement suppresses: is the subgroup hypothesis necessary? Precisely, if we take
arbitrary subsets $S\subseteq G$ and $T\subseteq\Gh$ with no algebraic structure assumed and
demand
\begin{equation}\label{eq:pair}
|G|\sum_{x\in S}f(x)\;=\;|S|\sum_{\psi\in T}\Fh f(\psi)\qquad\text{for all }f\colon G\to\mathbb{C},
\end{equation}
must $S$ be a subgroup and $T$ its annihilator? The answer is yes, with the single exception
$S=\emptyset$, for which both sides vanish identically. Poisson summation is therefore not
merely valid for subgroups; it \emph{characterises} them.

\subsection{Method}

Both sides of \eqref{eq:pair} are already understood objects, and the argument consists of
choosing the right test functions and invoking one elementary geometric fact. The two test
families are dual to each other: Dirac deltas $\delta_a$, which turn \eqref{eq:pair} into a
statement about a single row of the character table, and characters $\psi_0$, which turn it
into a statement about a single column. Since the deltas span $\mathbb{C}^{G}$, the first
reduction is lossless: the analytic-looking condition \eqref{eq:pair} is \emph{equivalent} to
a finite system of equations in the entries of the character table. What remains is settled by
the observation that $n$ complex numbers of modulus $1$ summing to $n$ are all equal to $1$.
That is the entire analytic content.

\section{Setting and notation}

Throughout, $G$ is a finite abelian group, written additively, of order $|G|$.

\begin{definition}[Character, dual group]
A \emph{character} of $G$ is a homomorphism $\psi\colon G\to\mathbb{C}^{\times}$. Since $G$ is
finite, each value $\psi(x)$ is a root of unity; in particular $|\psi(x)|=1$, $\psi(0)=1$ and
$\psi(-x)=\overline{\psi(x)}$. The set $\Gh$ of characters is an abelian group under pointwise
multiplication, with identity the trivial character $\one$, and $|\Gh|=|G|$.
\end{definition}

\begin{definition}[Discrete Fourier transform]
For $f\colon G\to\mathbb{C}$ and $\psi\in\Gh$, set
$\Fh f(\psi)=\sum_{x\in G}\overline{\psi(x)}f(x)$.
\end{definition}

\begin{definition}[Character table]
The \emph{character table} of $G$ is the matrix $(\psi(x))_{x\in G,\ \psi\in\Gh}$, all of whose
entries have modulus $1$.
\end{definition}

We use the orthogonality relation
\begin{equation}\label{eq:orth}
\sum_{x\in G}\psi(x)\overline{\chi(x)}=\begin{cases}|G| & \psi=\chi,\\ 0 & \psi\ne\chi,\end{cases}
\end{equation}
and the transform of a Dirac delta $\delta_a$ (equal to $1$ at $a$, zero elsewhere),
\begin{equation}\label{eq:delta}
\Fh{\delta_a}(\psi)=\overline{\psi(a)}.
\end{equation}

\begin{definition}[Annihilators]
For a subgroup $H\le G$ put $H^{\perp}=\{\psi\in\Gh:\psi(x)=1\ \forall x\in H\}\le\Gh$. For an
arbitrary subset $T\subseteq\Gh$ put $T^{\perp}=\{a\in G:\psi(a)=1\ \forall\psi\in T\}$.
\end{definition}

\begin{lemma}\label{lem:preannih}
For every subset $T\subseteq\Gh$, the set $T^{\perp}$ is a subgroup of $G$.
\end{lemma}

\begin{proof}
$\psi(0)=1$ for all $\psi$, so $0\in T^{\perp}$. If $\psi(a)=\psi(b)=1$ for all $\psi\in T$
then $\psi(a+b)=\psi(a)\psi(b)=1$ and $\psi(-a)=\overline{\psi(a)}=1$.
\end{proof}

Lemma \ref{lem:preannih} is the pivot of the paper: no hypothesis is placed on $T$, yet the
resulting set is automatically a group. We take as given the following two standard
consequences of \eqref{eq:orth}.

\begin{proposition}[Poisson summation]\label{prop:poisson}
For every subgroup $H\le G$ and every $f$, identity \eqref{eq:poisson} holds.
\end{proposition}

\begin{proposition}[Annihilator index]\label{prop:index}
For every subgroup $H\le G$, $|H|\cdot|H^{\perp}|=|G|$.
\end{proposition}

\section{Poisson pairs and reduction to the character table}

\begin{definition}[Poisson pair]\label{def:pair}
Let $S\subseteq G$, $T\subseteq\Gh$. The pair $(S,T)$ is a \emph{Poisson pair} if
$|G|\sum_{x\in S}f(x)=|S|\sum_{\psi\in T}\Fh f(\psi)$ for every $f\colon G\to\mathbb{C}$.
\end{definition}

By Proposition \ref{prop:poisson}, $(H,H^{\perp})$ is a Poisson pair for every subgroup $H$;
and $(\emptyset,T)$ is a Poisson pair for every $T$, both sides being zero. We prove there is
nothing else.

\begin{definition}[Character-table condition]
The pair $(S,T)$ satisfies the \emph{character-table condition} if for every $a\in G$,
\begin{equation}\label{eq:matrix}
|S|\sum_{\psi\in T}\overline{\psi(a)}\;=\;|G|\cdot\one_S(a).
\end{equation}
\end{definition}

\begin{theorem}[Delta reduction: only the deltas matter]\label{thm:delta}
$(S,T)$ is a Poisson pair if and only if it satisfies \eqref{eq:matrix}.
\end{theorem}

\begin{proof}
($\Rightarrow$) Apply the identity to $f=\delta_a$: the left side is $|G|\one_S(a)$ and, by
\eqref{eq:delta}, the right side is $|S|\sum_{\psi\in T}\overline{\psi(a)}$.

($\Leftarrow$) Expand both sides of Definition \ref{def:pair} as linear functionals in the
values $f(a)$:
\[
\sum_{x\in S}f(x)=\sum_{a\in G}\one_S(a)f(a),\qquad
\sum_{\psi\in T}\Fh f(\psi)=\sum_{a\in G}\Big(\sum_{\psi\in T}\overline{\psi(a)}\Big)f(a),
\]
the second by interchanging summations. The coefficients of $f(a)$ on the two sides are
$|G|\one_S(a)$ and $|S|\sum_{\psi\in T}\overline{\psi(a)}$, equal by hypothesis.
\end{proof}

Thus the quantification over all $f$ is equivalent to a finite statement about the character
table. The dual test function gives a complementary statement.

\begin{theorem}[Character test]\label{thm:chartest}
If $(S,T)$ is a Poisson pair then for every $\psi_0\in\Gh$,
\begin{equation}\label{eq:chartest}
\sum_{x\in S}\psi_0(x)\;=\;|S|\cdot\one_T(\psi_0).
\end{equation}
\end{theorem}

\begin{proof}
Take $f=\psi_0$. By \eqref{eq:orth}, $\Fh{\psi_0}(\chi)=|G|$ if $\chi=\psi_0$ and $0$
otherwise, so the right side of the Poisson identity is $|S|\,|G|\,\one_T(\psi_0)$ while the
left is $|G|\sum_{x\in S}\psi_0(x)$. Cancel $|G|\ne0$.
\end{proof}

\section{Rigidity}

\subsection{The equality case of the triangle inequality}

\begin{lemma}\label{lem:triangle}
Let $s$ be a finite index set and $(z_i)_{i\in s}$ complex numbers with $|z_i|=1$. If
$\sum_{i\in s}z_i=\#s$, then $z_i=1$ for every $i$.
\end{lemma}

\begin{proof}
Taking real parts, $\sum_{i\in s}(1-\operatorname{Re}z_i)=0$, and each summand is nonnegative
because $\operatorname{Re}z_i\le|z_i|=1$. Hence $\operatorname{Re}z_i=1$ for all $i$; combined
with $(\operatorname{Re}z_i)^2+(\operatorname{Im}z_i)^2=1$ this gives $\operatorname{Im}z_i=0$,
so $z_i=1$.
\end{proof}

Geometrically, $n$ unit vectors span a displacement of length $n$ only when identically
oriented. This is the only non-formal ingredient of the development.

\subsection{The trivial character and the area identity}

In this subsection $(S,T)$ is a Poisson pair with $S\ne\emptyset$.

\begin{lemma}\label{lem:trivchar}
The trivial character lies in $T$; in particular $T\ne\emptyset$.
\end{lemma}

\begin{proof}
Apply \eqref{eq:chartest} with $\psi_0=\one$: the left side is $|S|$, so
$|S|=|S|\one_T(\one)$, and $|S|\ne0$ gives $\one\in T$.
\end{proof}

\begin{theorem}[Area identity]\label{thm:area}
$|S|\cdot|T|=|G|$.
\end{theorem}

\begin{proof}
Evaluate \eqref{eq:matrix} at $a=0$. Since $\psi(0)=1$ for all $\psi$, the left side is
$|S||T|$ and the right is $|G|\one_S(0)$. If $0\notin S$ we would get $|S||T|=0$, contradicting
$S\ne\emptyset$ and Lemma \ref{lem:trivchar}. Hence $0\in S$ and $|S||T|=|G|$.
\end{proof}

\begin{corollary}[Lagrange's theorem from Poisson summation]\label{cor:lagrange}
$|S|$ divides $|G|$.
\end{corollary}

The divisibility is obtained directly from the analytic identity, before any group structure
on $S$ is known.

\subsection{Membership is detected by the character table}

\begin{theorem}[Rigidity, primal side]\label{thm:primal}
For every $a\in G$: $\;a\in S\iff\psi(a)=1$ for all $\psi\in T$.
\end{theorem}

\begin{proof}
($\Rightarrow$) If $a\in S$ then \eqref{eq:matrix} and Theorem \ref{thm:area} give
$|S|\sum_{\psi\in T}\overline{\psi(a)}=|G|=|S||T|$, so $\sum_{\psi\in T}\overline{\psi(a)}=|T|$,
a sum of $|T|$ unimodular numbers attaining $|T|$. Lemma \ref{lem:triangle} gives
$\overline{\psi(a)}=1$, i.e.\ $\psi(a)=1$, for all $\psi\in T$.

($\Leftarrow$) If $\psi(a)=1$ for all $\psi\in T$ but $a\notin S$, the left side of
\eqref{eq:matrix} is $|S||T|\ne0$ while the right side is $0$.
\end{proof}

\begin{theorem}[Rigidity, dual side]\label{thm:dual}
For every $\psi\in\Gh$: $\;\psi\in T\iff\psi(x)=1$ for all $x\in S$.
\end{theorem}

\begin{proof}
($\Rightarrow$) If $\psi\in T$ then \eqref{eq:chartest} gives $\sum_{x\in S}\psi(x)=|S|$;
apply Lemma \ref{lem:triangle}.
($\Leftarrow$) If $\psi(x)=1$ on $S$ then $\sum_{x\in S}\psi(x)=|S|\ne0$, so
$\one_T(\psi)\ne0$ by \eqref{eq:chartest}.
\end{proof}

\subsection{The converse}

\begin{theorem}[Converse of Poisson summation]\label{thm:converse}
Let $S\subseteq G$ be nonempty, $T\subseteq\Gh$, and suppose $(S,T)$ is a Poisson pair. Then
$H:=T^{\perp}$ is a subgroup of $G$ with $S=H$ and $T=H^{\perp}$.
\end{theorem}

\begin{proof}
$H$ is a subgroup by Lemma \ref{lem:preannih}. Theorem \ref{thm:primal} states exactly that
$a\in S\iff a\in T^{\perp}$, so $S=H$; Theorem \ref{thm:dual} then states that $\psi\in T$ iff
$\psi$ is trivial on $H$, i.e.\ $T=H^{\perp}$.
\end{proof}

\begin{theorem}[Classification]\label{thm:classification}
For nonempty $S$, the pair $(S,T)$ is a Poisson pair if and only if there is a subgroup
$H\le G$ with $S=H$ and $T=H^{\perp}$.
\end{theorem}

\begin{proof}
Necessity is Theorem \ref{thm:converse}; sufficiency is Proposition \ref{prop:poisson}.
\end{proof}

\begin{proposition}[Sharpness]\label{prop:empty}
$(\emptyset,T)$ is a Poisson pair for every $T$, both sides of the identity being zero. Hence
the nonemptiness hypothesis cannot be dropped, and $S=\emptyset$ is the only exception.
\end{proposition}

\begin{corollary}[Uniqueness]\label{cor:unique}
Let $S$ be nonempty. If $(S,T)$ and $(S,T')$ are Poisson pairs then $T=T'$; if $(S,T)$ and
$(S',T)$ are Poisson pairs with $S,S'$ nonempty then $S=S'$.
\end{corollary}

\begin{proof}
Immediate from Theorems \ref{thm:dual} and \ref{thm:primal}, each of which characterises one
side purely in terms of the other.
\end{proof}

\begin{corollary}[Biduality]\label{cor:biduality}
$(H^{\perp})^{\perp}=H$ for every subgroup $H\le G$.
\end{corollary}

\begin{proof}
$(H,H^{\perp})$ is a Poisson pair with $H\ni0$ nonempty; Theorem \ref{thm:primal} says
$a\in H$ iff $\psi(a)=1$ for all $\psi\in H^{\perp}$, i.e.\ iff $a\in (H^{\perp})^{\perp}$.
\end{proof}

The finite case of Pontryagin biduality thus emerges as a consequence of the analytic
identity rather than as an ingredient of its proof.

\section{Extremal rectangles and enumeration}

\subsection{The rectangle picture}

\begin{definition}
A pair $(S,T)$ is an \emph{all-ones rectangle} if $\psi(x)=1$ for every $x\in S$ and every
$\psi\in T$. Its \emph{area} is $|S|\cdot|T|$.
\end{definition}

\begin{theorem}[Rectangle bound]\label{thm:rectbound}
Every all-ones rectangle satisfies $|S|\cdot|T|\le|G|$.
\end{theorem}

\begin{proof}
Put $H=T^{\perp}$, a subgroup by Lemma \ref{lem:preannih}. The hypothesis gives $S\subseteq H$;
and every $\psi\in T$ is trivial on $H$ by definition of $T^{\perp}$, so $T\subseteq H^{\perp}$.
Hence $|S||T|\le|H||H^{\perp}|=|G|$ by Proposition \ref{prop:index}.
\end{proof}

\begin{theorem}[Rectangle criterion]\label{thm:rect}
Let $S\ne\emptyset$. Then $(S,T)$ is a Poisson pair if and only if $S\times T$ is an all-ones
rectangle with $|S|\cdot|T|=|G|$.
\end{theorem}

\begin{proof}
($\Rightarrow$) The all-ones property is Theorem \ref{thm:dual}; the area is Theorem
\ref{thm:area}.

($\Leftarrow$) Put $H=T^{\perp}$. As above $S\subseteq H$ and $T\subseteq H^{\perp}$, so
$|S|\le|H|$ and $|T|\le|H^{\perp}|$, with $|S|>0$ and $|T|>0$ because $|S||T|=|G|>0$. Then
$|S||T|\le|H||T|\le|H||H^{\perp}|=|G|=|S||T|$ forces equality throughout, and cancelling the
positive factors gives $|S|=|H|$, $|T|=|H^{\perp}|$. Combined with the inclusions this yields
$S=H$ and $T=H^{\perp}$, and Proposition \ref{prop:poisson} applies.
\end{proof}

Analysis has now completely evaporated: the character table of a finite abelian group has the
property that all its maximal all-ones rectangles have the same area $|G|$, and each is a
subgroup paired with its annihilator.

\subsection{The bijection with the subgroup lattice}

Let $\mathcal{P}(G)$ denote the set of Poisson pairs with $S\ne\emptyset$ and $\Sub(G)$ the set
of subgroups of $G$.

\begin{theorem}[Poisson pairs are the subgroup lattice]\label{thm:bijection}
The map $\Phi(S,T)=T^{\perp}$ is a bijection $\mathcal{P}(G)\to\Sub(G)$, with inverse
$\Psi(H)=(H,H^{\perp})$.
\end{theorem}

\begin{proof}
$\Phi$ is well defined by Lemma \ref{lem:preannih}, and $\Psi$ by Proposition
\ref{prop:poisson}. For a subgroup $H$, $\Phi(\Psi(H))=(H^{\perp})^{\perp}=H$ by Corollary
\ref{cor:biduality}. Conversely, for $(S,T)\in\mathcal{P}(G)$ with $H=T^{\perp}$, Theorem
\ref{thm:converse} gives $S=H$ and $T=H^{\perp}$, i.e.\ $\Psi(\Phi(S,T))=(S,T)$.
\end{proof}

\begin{corollary}[Exact count]\label{cor:count}
$\#\mathcal{P}(G)=\#\Sub(G)$.
\end{corollary}

\begin{theorem}[Groups of prime order]\label{thm:prime}
If $|G|=p$ is prime, $S\ne\emptyset$ and $(S,T)$ is a Poisson pair, then
$(S,T)=(\{0\},\Gh)$ or $(S,T)=(G,\{\one\})$; conversely both are Poisson pairs.
\end{theorem}

\begin{proof}
By Theorem \ref{thm:area}, $|S|$ divides $p$, so $|S|\in\{1,p\}$; since $0\in S$, in the first
case $S=\{0\}$ and in the second $S=G$. The dual side is then determined by Corollary
\ref{cor:unique}. Both stated pairs are all-ones rectangles of area $p$ (one row by all $p$
columns; all $p$ rows by the trivial-character column), so Theorem \ref{thm:rect} applies.
\end{proof}

The two survivors are Fourier inversion at the origin and the definition of the zeroth Fourier
coefficient. In a group of prime order these are \emph{all} the Poisson identities.

\subsection{The cyclic case}

For $G=\mathbb{Z}/n$ the characters are $\psi_k(x)=e^{2\pi ikx/n}$, and $\psi_k(x)=1$ exactly
when $n\mid kx$. Theorem \ref{thm:rect} therefore becomes purely arithmetic.

\begin{corollary}
For nonempty $S\subseteq\mathbb{Z}/n$ and $T\subseteq\mathbb{Z}/n$, the pair $(S,T)$ is a
Poisson pair if and only if $n\mid xk$ for all $x\in S$, $k\in T$, and $|S|\cdot|T|=n$.
\end{corollary}

Since the subgroups of $\mathbb{Z}/n$ correspond to divisors of $n$, Corollary \ref{cor:count}
predicts $\#\mathcal{P}(\mathbb{Z}/n)=\sigma_0(n)$. Exhaustive search over all $4^{n}$ pairs of
subsets confirms this for small $n$:

\begin{center}
\begin{tabular}{lcccccc}
\toprule
$n$ & 1 & 2 & 3 & 4 & 5 & 6\\
\midrule
number of Poisson pairs & 1 & 2 & 2 & 3 & 2 & 4\\
$\sigma_0(n)$ & 1 & 2 & 2 & 3 & 2 & 4\\
\bottomrule
\end{tabular}
\end{center}

For $n=6$ the four pairs correspond to the subgroups $\{0\}$, $\{0,3\}$, $\{0,2,4\}$,
$\mathbb{Z}/6$, with dual sides of sizes $6,3,2,1$, realising $|S||T|=6$ in each case.

\section{The boundary of rigidity: twisted Poisson summation}

Cosets, the natural next candidate after subgroups, satisfy a Poisson identity at the cost of
a phase.

\begin{proposition}[Poisson summation over a coset]\label{prop:coset}
For $H\le G$, $a\in G$ and every $f$,
\[
|G|\sum_{x\in a+H}f(x)\;=\;|H|\sum_{\psi\in H^{\perp}}\psi(a)\,\Fh f(\psi).
\]
\end{proposition}

\begin{proof}[Proof sketch]
Apply \eqref{eq:poisson} to $g(x)=f(x+a)$ and use the covariance
$\Fh g(\psi)=\psi(a)\Fh f(\psi)$, itself the substitution $y=x+a$ together with
$\overline{\psi(y-a)}=\psi(a)\overline{\psi(y)}$.
\end{proof}

\begin{definition}[Twisted Poisson pair]
For $S\subseteq G$, $T\subseteq\Gh$ and $w\colon\Gh\to\mathbb{C}$, the triple $(S,T,w)$ is a
\emph{twisted Poisson pair} if $|G|\sum_{x\in S}f(x)=|S|\sum_{\psi\in T}w(\psi)\Fh f(\psi)$
for all $f$.
\end{definition}

\begin{theorem}[Twisted converse, unimodular weights]\label{thm:twisted}
Let $(S,T,w)$ be a twisted Poisson pair with $S\ne\emptyset$ and $|w(\psi)|=1$ on $T$. Then
there are a subgroup $H\le G$ and $a\in G$ with $S=a+H$, $T=H^{\perp}$ and $w(\psi)=\psi(a)$
on $T$.
\end{theorem}

\begin{proof}[Proof sketch]
Testing against deltas as in Theorem \ref{thm:delta} gives
$|S|\sum_{\psi\in T}w(\psi)\overline{\psi(a)}=|G|\one_S(a)$. Evaluating at a point
$a_0\in S$ recovers the area identity and presents a sum of $|T|$ unimodular numbers attaining
$|T|$, so Lemma \ref{lem:triangle} forces $w(\psi)=\psi(a_0)$ on $T$. Substituting back removes
the twist from the translated pair $(S-a_0,T)$, which is then an untwisted Poisson pair;
Theorem \ref{thm:converse} identifies it as $(H,H^{\perp})$.
\end{proof}

\begin{theorem}[Collapse without unimodularity]\label{thm:collapse}
For every nonempty $S\subseteq G$, the triple $(S,\Gh,w)$ with
$w(\psi)=\overline{\Fh{\one_S}(\psi)}/|S|$ is a twisted Poisson pair.
\end{theorem}

\begin{proof}[Proof sketch]
By Fourier inversion, $\sum_{\psi}\overline{\Fh{\one_S}(\psi)}\,\Fh f(\psi)$ reproduces
$|G|\sum_{x\in S}f(x)$ for every $f$; divide by $|S|$.
\end{proof}

Thus without a normalisation constraint the notion is vacuous: every nonempty subset is a
twisted Poisson set. An explicit witness that this is not an artefact is
$S=\{0,1\}\subseteq\mathbb{Z}/3$, which cannot be a coset since $2\nmid3$, yet carries a valid
twisted identity. Unimodularity of the weight is therefore not a technical convenience: it is
exactly the hypothesis separating the rigid regime from the vacuous one, as the shape of the
proof --- whose only substantive step is a statement about unit vectors --- predicts.

\section{Application: the equality case of the uncertainty principle}

For $f\colon G\to\mathbb{C}$ write $\supp f=\{x:f(x)\ne0\}$.

\begin{theorem}[Donoho--Stark uncertainty principle]\label{thm:ds}
For every $f\ne0$, $\;|\supp f|\cdot|\supp\Fh f|\ge|G|$.
\end{theorem}

\begin{proof}[Proof sketch]
With $A=\supp f$, $B=\supp\Fh f$ and $M=\max_x|f(x)|$, Fourier inversion gives
$|G|M\le\sum_{\psi\in B}\|\Fh f(\psi)\|\le|B|\,\|f\|_1\le|B||A|M$.
\end{proof}

\begin{theorem}[Extremals]\label{thm:extremals}
For $f\ne0$, equality $|\supp f|\cdot|\supp\Fh f|=|G|$ holds if and only if there are a
subgroup $H\le G$, an element $a\in G$, a character $\psi_1\in\Gh$ and a constant $c\ne0$ with
$f=c\,\psi_1\one_{a+H}$.
\end{theorem}

\begin{proof}[Proof sketch]
Sufficiency is a computation: the transform of $c\psi_1\one_{a+H}$ is supported exactly on the
coset $\psi_1H^{\perp}$ of size $|G|/|H|$.

Necessity runs the chain in Theorem \ref{thm:ds} backwards. Equality throughout forces
\emph{double flatness}: $|f|$ is constant on $\supp f$ and $|\Fh f|$ is constant on
$\supp\Fh f$. Double flatness plus inversion forces, for each $x\in\supp f$, the phases
$\psi\mapsto\psi(x)\Fh f(\psi)$ to be independent of $\psi\in\supp\Fh f$. Comparing this
relation at two points $x,a\in\supp f$ and two characters $\psi,\psi_1\in\supp\Fh f$ makes the
block $(\supp f-a)\times(\supp\Fh f\cdot\psi_1^{-1})$ of the character table identically $1$,
of area $|\supp f||\supp\Fh f|=|G|$. By Theorem \ref{thm:rect} this is a Poisson pair, so by
Theorem \ref{thm:converse} $\supp f-a=H$ is a subgroup and $\supp\Fh f=\psi_1H^{\perp}$;
flatness and constancy of phase give $f=c\psi_1\one_{a+H}$.
\end{proof}

The extremals therefore form exactly one orbit of the natural symmetry group of the problem
(scaling $\times$ translation $\times$ modulation) acting on subgroup indicators.

\section{Algorithms}

Write $n=|G|$.

\emph{Poisson-pair verification.} By Theorem \ref{thm:rect} it suffices to check
$|S||T|=n$ and $\psi(x)=1$ on $S\times T$: cost $O(n)$ character-table lookups once the area
test passes. Verifying Definition \ref{def:pair} directly is impossible (infinitely many test
functions); via Theorem \ref{thm:delta} it costs $O(n^2)$.

\emph{Poisson-pair enumeration.} By Theorem \ref{thm:bijection} it suffices to enumerate the
subgroups $H$ and output $(H,H^{\perp})$. For $G=\mathbb{Z}/n$ this is a divisor listing,
$O(\sqrt n)$ to find the divisors and $O(n)$ to write out the pairs, versus $4^{n}$ for the
brute-force search used as an independent check.

\emph{Extremal recognition.} Compute $\Fh f$ ($O(n\log n)$ by a fast transform), test
$|\supp f|\cdot|\supp\Fh f|=n$; if it holds, Theorem \ref{thm:extremals} supplies the data:
$a$ any point of $\supp f$, $H=\supp f-a$, $\psi_1$ any character in $\supp\Fh f$, and
$c=f(a)/\psi_1(a)$.

\section{Discussion}

Three readings of the converse deserve emphasis. First, \emph{Poisson summation contains
Lagrange's theorem}: the divisibility $|S|\mid|G|$ of Corollary \ref{cor:lagrange} is derived
before any group structure on $S$ is available. Second, \emph{Poisson summation contains
biduality}: Corollary \ref{cor:biduality} recovers $H^{\perp\perp}=H$ without invoking the
structure theorem for finite abelian groups. Third, \emph{Poisson summation is a combinatorial
extremality statement}: Theorem \ref{thm:rect} replaces the identity by ``all-ones rectangle
of area $|G|$'', a form that generalises to any table of unimodular numbers with an
orthogonality relation.

The single source of rigidity is Lemma \ref{lem:triangle}. The Poisson identity, tested at a
delta or at a character, always presents itself as a saturated sum of unit vectors, leaving no
slack for an unstructured $S$. Section 6 confirms the diagnosis by withdrawing unimodularity
and watching the theory collapse.

Finally, Theorem \ref{thm:ds} is the theoretical justification for uniqueness in sparse
recovery, and Theorem \ref{thm:extremals} identifies its exact worst cases: the
coset-supported modulated indicators, forming a single symmetry orbit.

\section{Future directions}

\begin{conjecture}[Non-abelian Poisson pairs detect normal subgroups]
Let $G$ be a finite group with irreducible characters $\Irr G$. Call $(S,T)$, $S\subseteq G$,
$T\subseteq\Irr G$, a Poisson pair if
$|G|\sum_{x\in S}f(x)=|S|\sum_{\chi\in T}d_{\chi}\langle f,\chi\rangle$ for every class
function $f$. Then the nonempty Poisson pairs are exactly the pairs $(N,\Irr(G/N))$ with
$N\trianglelefteq G$.
\end{conjecture}
The abelian proof never used commutativity except through the character table: Theorem
\ref{thm:rect} reduces everything to an all-ones block of maximal area, and in the non-abelian
class character table the all-ones blocks should be exactly the kernels of quotients. A
counterexample would be a finite group with a non-normal Poisson pair --- a finite search.

\begin{conjecture}[Self-duality]
$(S,T)$ is a nonempty Poisson pair for $G$ if and only if $(T,\iota(S))$ is a nonempty Poisson
pair for $\Gh$, where $\iota\colon G\to\widehat{\Gh}$ is the canonical embedding.
\end{conjecture}
Theorem \ref{thm:rect} reduces the condition to a $0/1$ matrix statement, and that matrix is
the transpose of the corresponding matrix for $\Gh$, with $|\Gh|=|G|$.

\begin{conjecture}[Stability]
There is an absolute constant $C$ such that if $S\ne\emptyset$, $|w(\psi)|=1$ on $T$ and
\[
\Big|\,|G|\sum_{x\in S}f(x)-|S|\sum_{\psi\in T}w(\psi)\Fh f(\psi)\,\Big|
\le\varepsilon|G||S|\|f\|_{\infty}\quad\text{for all }f,
\]
then there is a coset $a+H$ with $|S\,\triangle\,(a+H)|\le C\varepsilon|S|$.
\end{conjecture}
The exact proof turns on a single equality case, and that equality case is stable:
$|\sum z_i|\ge(1-\varepsilon)n$ with $|z_i|=1$ forces all but $O(\sqrt\varepsilon n)$ of the
$z_i$ to lie within $O(\sqrt\varepsilon)$ of $1$.

\begin{conjecture}[Quantitative enumeration]
Corollary \ref{cor:count} turns the count of Poisson pairs into a subgroup count; for
$G=(\mathbb{Z}/p)^k$ this is the Galois number $\sum_j\binom{k}{j}_p$, growing like
$p^{k^2/4}$. Characterise the attainable growth rates of $\#\mathcal{P}(G)$ and the extremal
groups of a given order.
\end{conjecture}

\begin{conjecture}[Weighted uncertainty extremals]
Entropic and $\ell^p$ variants of the uncertainty principle have their own equality cases; the
method here --- read equality back through the chain, extract a maximal all-ones rectangle,
invoke the converse of Poisson summation --- should adapt and identify how much of the ``one
orbit'' phenomenon is specific to counting supports.
\end{conjecture}

\section{Conclusion}

Poisson summation on a finite abelian group holds for subgroups paired with their
annihilators, and for nothing else. Quantified over arbitrary pairs of subsets, the identity
forces the primal side to be a subgroup and the dual side to be its annihilator, with the
empty set as the unique degenerate solution. The proof reduces the identity to a finite
statement about the character table by testing against Dirac deltas and characters, and then
invokes a single geometric fact about unit vectors. The classification converts into an exact
enumeration --- the nonempty Poisson pairs are in bijection with the subgroup lattice --- and
yields Lagrange's theorem, biduality and the equality case of the uncertainty principle as
corollaries. Twisting the identity with weights delimits the theorem exactly: unimodular
weights preserve full rigidity, arbitrary weights destroy it.

