"""Enumeration of all Poisson pairs of a finite abelian group via its subgroup lattice.

The nonempty pairs (S, T) satisfying |G| sum_{x in S} f(x) = |S| sum_{psi in T} fhat(psi)
for all f are exactly the pairs (H, H^perp) with H a subgroup.  Enumerating them therefore
means enumerating subgroups: cost O(#subgroups * |G|) instead of the 4^{|G|} cost of a naive
search over pairs of subsets.
"""

from __future__ import annotations

import itertools
import math
from typing import Dict, Iterable, List, Sequence, Set, Tuple

Group = Tuple[int, ...]
Moduli = Tuple[int, ...]


def elements(moduli: Moduli) -> List[Group]:
    """All elements of Z/n1 x ... x Z/nk."""
    return [tuple(t) for t in itertools.product(*(range(n) for n in moduli))]


def add(x: Group, y: Group, moduli: Moduli) -> Group:
    """Componentwise addition modulo the moduli."""
    return tuple((a + b) % n for a, b, n in zip(x, y, moduli))


def closure(gens: Iterable[Group], moduli: Moduli) -> Tuple[Group, ...]:
    """The subgroup generated by `gens`, by breadth-first closure under addition."""
    zero = tuple(0 for _ in moduli)
    seen: Set[Group] = {zero}
    stack = [zero]
    gens = list(gens)
    while stack:
        x = stack.pop()
        for g in gens:
            y = add(x, g, moduli)
            if y not in seen:
                seen.add(y)
                stack.append(y)
    return tuple(sorted(seen))


def subgroups(moduli: Moduli) -> List[Tuple[Group, ...]]:
    """All subgroups: closures of all generating sets of size at most log2|G|."""
    order = math.prod(moduli)
    elts = elements(moduli)
    max_gens = max(1, int(math.log2(order)) + 1)
    found: Set[Tuple[Group, ...]] = set()
    for r in range(max_gens + 1):
        for gens in itertools.combinations(elts, r):
            found.add(closure(gens, moduli))
    return sorted(found, key=lambda H: (len(H), H))


def character_is_one(k: Group, x: Group, moduli: Moduli) -> bool:
    """Whether psi_k(x) = 1, tested exactly in integer arithmetic."""
    order = math.prod(moduli)
    total = sum((k_j * x_j) % n_j * (order // n_j) for k_j, x_j, n_j in zip(k, x, moduli))
    return total % order == 0


def annihilator(H: Sequence[Group], moduli: Moduli) -> Tuple[Group, ...]:
    """H^perp = { psi : psi trivial on H }, indexed by dual coordinates."""
    return tuple(k for k in elements(moduli)
                 if all(character_is_one(k, x, moduli) for x in H))


def poisson_pairs(moduli: Moduli) -> List[Tuple[Tuple[Group, ...], Tuple[Group, ...]]]:
    """All nonempty Poisson pairs of G, one for each subgroup."""
    return [(H, annihilator(H, moduli)) for H in subgroups(moduli)]


if __name__ == "__main__":
    for moduli in [(6,), (8,), (2, 2), (2, 6)]:
        pairs = poisson_pairs(moduli)
        order = math.prod(moduli)
        assert all(len(S) * len(T) == order for S, T in pairs)   # area identity
        print(f"G = {moduli}, |G| = {order}: {len(pairs)} Poisson pairs, "
              f"sizes {[ (len(S), len(T)) for S, T in pairs ]}")
